class Solution:
    def minimumScore(self, s: str, t: str) -> int:
        n, m, INF = len(s), len(t), float('inf')
        pre = [0] * (m + 1)
        i = 0
        for j in range(1, m + 1):
            while i < n and s[i] != t[j - 1]:
                i += 1
            pre[j] = i + 1 if i < n else INF
            if i < n:
                i += 1
        suf = [0] * (m + 1)
        i = n - 1
        for j in range(m - 1, -1, -1):
            while i >= 0 and s[i] != t[j]:
                i -= 1
            suf[j] = n - i if i >= 0 else INF
            if i >= 0:
                i -= 1
        if pre[m] <= n:
            return 0
        ans, y = m, 0
        for x in range(m + 1):
            if pre[x] == INF:
                break
            while y < m and (y < x or pre[x] + suf[y] > n):
                y += 1
            ans = min(ans, y - x)
        return ans

