class Solution {
public:
    int minimumScore(string s, string t) {
        int n = s.size(), m = t.size();
        const int INF = INT_MAX / 2;
        vector<int> pre(m + 1, 0), suf(m + 1, 0);
        int i = 0;
        for (int j = 1; j <= m; ++j) {
            while (i < n && s[i] != t[j - 1]) ++i;
            pre[j] = i < n ? i + 1 : INF;
            if (i < n) ++i;
        }
        i = n - 1;
        for (int j = m - 1; j >= 0; --j) {
            while (i >= 0 && s[i] != t[j]) --i;
            suf[j] = i >= 0 ? n - i : INF;
            if (i >= 0) --i;
        }
        if (pre[m] <= n) return 0;
        int ans = m, y = 0;
        for (int x = 0; x <= m && pre[x] < INF; ++x) {
            while (y < m && (y < x || (long long)pre[x] + suf[y] > n)) ++y;
            ans = min(ans, y - x);
        }
        return ans;
    }
};

