class Solution {
    public int minimumScore(String s, String t) {
        int n = s.length(), m = t.length();
        final int INF = Integer.MAX_VALUE / 2;
        int[] pre = new int[m + 1], suf = new int[m + 1];
        int i = 0;
        for (int j = 1; j <= m; ++j) {
            while (i < n && s.charAt(i) != t.charAt(j - 1)) ++i;
            pre[j] = i < n ? i + 1 : INF;
            if (i < n) ++i;
        }
        i = n - 1;
        for (int j = m - 1; j >= 0; --j) {
            while (i >= 0 && s.charAt(i) != t.charAt(j)) --i;
            suf[j] = i >= 0 ? n - i : INF;
            if (i >= 0) --i;
        }
        if (pre[m] <= n) return 0;
        int ans = m, y = 0;
        for (int x = 0; x <= m && pre[x] < INF; ++x) {
            while (y < m && (y < x || (long) pre[x] + suf[y] > n)) ++y;
            ans = Math.min(ans, y - x);
        }
        return ans;
    }
}

