var minimumScore = function(s, t) {
    const n = s.length, m = t.length, INF = Infinity;
    const pre = new Array(m + 1).fill(0), suf = new Array(m + 1).fill(0);
    let i = 0;
    for (let j = 1; j <= m; ++j) {
        while (i < n && s[i] !== t[j - 1]) ++i;
        pre[j] = i < n ? i + 1 : INF;
        if (i < n) ++i;
    }
    i = n - 1;
    for (let j = m - 1; j >= 0; --j) {
        while (i >= 0 && s[i] !== t[j]) --i;
        suf[j] = i >= 0 ? n - i : INF;
        if (i >= 0) --i;
    }
    if (pre[m] <= n) return 0;
    let ans = m, y = 0;
    for (let x = 0; x <= m && pre[x] < INF; ++x) {
        while (y < m && (y < x || pre[x] + suf[y] > n)) ++y;
        ans = Math.min(ans, y - x);
    }
    return ans;
};
